theorem coprime_combine {u v m k : ℕ}
    (hm : m = u + v ∨ (m = u - v ∧ v ≤ u) ∨ (m = v - u ∧ u ≤ v))
    (hdvd : k ∣ v) (hu : Nat.Coprime u k) : Nat.Coprime m k

theorem coprime_combine' {u v m k : ℕ}
    (hm : m = u + v ∨ (m = u - v ∧ v ≤ u) ∨ (m = v - u ∧ u ≤ v))
    (hdvd : k ∣ u) (hv : Nat.Coprime v k) : Nat.Coprime m k

theorem modEq_sum {ι : Type _} {S : Finset ι} {f g : ι → ℕ} {n : ℕ}
    (h : ∀ i ∈ S, f i ≡ g i [MOD n]) :
    ∑ i ∈ S, f i ≡ ∑ i ∈ S, g i [MOD n]

theorem int_modEq_sum {ι : Type _} {S : Finset ι} {f g : ι → ℤ} {n : ℤ}
    (h : ∀ i ∈ S, f i ≡ g i [ZMOD n]) :
    ∑ i ∈ S, f i ≡ ∑ i ∈ S, g i [ZMOD n]

theorem not_isSquare_disc {n : ℕ} (hn : n.Prime) {u a : ℤ}
    (hJ : jacobiSym (u ^ 2 + 4 * a) n = -1) :
    ¬ IsSquare ((u : ZMod n) ^ 2 + 4 * (a : ZMod n))

theorem quad_irreducible {n : ℕ} (hn : n.Prime) {u a : ZMod n}
    (hns : ¬ IsSquare (u ^ 2 + 4 * a)) :
    Irreducible (X ^ 2 - C u * X - C a : Polynomial (ZMod n))

theorem padicValNat_prod_pow {p : ℕ} (hp : p.Prime) {S : Finset ℕ}
    (hS : ∀ q ∈ S, q.Prime) (e : ℕ → ℕ) (hpS : p ∈ S) :
    padicValNat p (∏ q ∈ S, q ^ e q) = e p

theorem zeta_pow_eq_neg_sum {R : Type _} [CommRing R] {P k : ℕ}
    (hp : P.Prime) (hk : 0 < k) {z : R}
    (hz : Polynomial.eval₂ (Int.castRingHom R) z
      (cyclotomic (P ^ k) ℤ) = 0)
    {l : ℕ} (hl : (P - 1) * P ^ (k - 1) ≤ l) :
    z ^ l = - ∑ i ∈ Finset.Icc 1 (P - 1), z ^ (l - i * P ^ (k - 1))

theorem jacobiSum_eq_sum_gen_pow {R : Type _} [CommRing R] {q : ℕ}
    [Fact q.Prime] {gu : (ZMod q)ˣ}
    (hg : ∀ u : (ZMod q)ˣ, u ∈ Subgroup.zpowers gu)
    {χ : MulChar (ZMod q) R} {f : ℕ → ℕ}
    (hf : ∀ x ∈ Finset.Icc 1 (q - 2),
      ((gu : ZMod q)) ^ f x = 1 - ((gu : ZMod q)) ^ x)
    (a b : ℕ) :
    jacobiSum (χ ^ a) (χ ^ b)
      = ∑ x ∈ Finset.Icc 1 (q - 2), (χ ↑gu) ^ (a * x + b * f x)

theorem factorization_eq_succ_of_dvd_mul_prime {ω M p : ℕ}
    (hp : p.Prime) (hM0 : M ≠ 0) (hω0 : ω ≠ 0) (h1 : ω ∣ M * p)
    (h2 : ¬ ω ∣ M) : ω.factorization p = M.factorization p + 1

theorem norm_one_denominator_isUnit {n : ℕ} (hn : n.Prime) {u a : ZMod n}
    (hns : ¬ IsSquare (u ^ 2 + 4 * a)) (m : ZMod n) :
    IsUnit (m * (m + u) - a)

theorem isUnit_of_isUnit_prod {M ι : Type _} [CommMonoid M]
    {s : Finset ι} {f : ι → M} (h : IsUnit (∏ i ∈ s, f i)) {i : ι}
    (hi : i ∈ s) : IsUnit (f i)

theorem eq_zero_of_evAt_eq_zero {c₁ c₂ : ZMod r} (hc₁ : c₁ ^ 2 - u * c₁ - a = 0)
    (hc₂ : c₂ ^ 2 - u * c₂ - a = 0) (hne : c₁ ≠ c₂) {y : QuadRing (ZMod r) u a}
    (h₁ : evAt u a hc₁ y = 0) (h₂ : evAt u a hc₂ y = 0) : y = 0

theorem span_natCast_natCast_imp_dvd (hm : 0 < m) :
    ∀ a : ℕ, ((a : ℕ) : CycM m) ∈ Ideal.span {((n : ℕ) : CycM m)}
      → n ∣ a

theorem span_natCast_sigmaN_mem (hm : 0 < m) (hco : Nat.Coprime n m) :
    ∀ x ∈ Ideal.span {((n : ℕ) : CycM m)},
      sigmaN hm hco x ∈ Ideal.span {((n : ℕ) : CycM m)}

theorem dvd_prod_sub_prod {ι R : Type _} [CommRing R] {c : R}
    {f g : ι → R} : ∀ {S : Finset ι}, (∀ i ∈ S, c ∣ f i - g i) →
      c ∣ ∏ i ∈ S, f i - ∏ i ∈ S, g i

theorem sigmaN_sub_pow_mem (hm : 0 < m) (hn : n.Prime)
    (hco : Nat.Coprime n m) (α : CycM m) :
    sigmaN hm hco α - α ^ n ∈ Ideal.span {((n : ℕ) : CycM m)}

theorem coprime_s1_s2 {t' n F s2bar : ℕ}
    (hq : ∀ q ∈ s2bar.primeFactors, ¬ q ∣ F) :
    Nat.Coprime (s1 t' F) (s2 t' n s2bar)

theorem cyclotomic_prime_pow_eq_sum {R : Type _} [CommRing R] {p k : ℕ}
    (hp : p.Prime) (hk : 0 < k) :
    cyclotomic (p ^ k) R = ∑ i ∈ Finset.range p, X ^ (i * p ^ (k - 1))

theorem sum_pow_root_cyclotomic_eq_zero {R : Type _} [CommRing R] {p k : ℕ}
    (hp : p.Prime) (hk : 0 < k) {z : R}
    (hz : eval₂ (Int.castRingHom R) z (cyclotomic (p ^ k) ℤ) = 0)
    {x : ℕ} (hx : ¬ p ∣ x) (c : ℕ) :
    ∑ l ∈ range p, z ^ (c + x * l * p ^ (k - 1)) = 0

theorem findH_spec {R : Type _} [CommRing R] [DecidableEq R] {p k : ℕ}
    (hp : p.Prime) (hk : 0 < k) {z : R}
    (hz : eval₂ (Int.castRingHom R) z (cyclotomic (p ^ k) ℤ) = 0)
    (a : ℕ → R) {h : ℕ} (hfind : findH p k a = some h) :
    ∑ i ∈ range ((p - 1) * p ^ (k - 1)), a i * z ^ i = z ^ h

theorem sub_mem_mKernel_iff {F : Type _} [CommRing F] {m : ℕ} {z : F}
    (hz : eval₂ (Int.castRingHom F) z (cyclotomic m ℤ) = 0) (u v : CP.CycM m) :
    u - v ∈ mKernel m hz ↔ lambdaHom m hz u = lambdaHom m hz v

theorem intCast_mem_imp_dvd {𝔪 : Ideal (CycM m)}
    (hIZ : ∀ a : ℕ, ((a : ℕ) : CycM m) ∈ 𝔪 → n ∣ a) :
    ∀ b : ℤ, ((b : ℤ) : CycM m) ∈ 𝔪 → (n : ℤ) ∣ b

theorem orderOf_pow_odd {M : Type _} [Monoid M] {a : M} {K x : ℕ}
    (hord : orderOf a = 2 ^ K) (hx : ¬ 2 ∣ x) :
    orderOf (a ^ x) = 2 ^ K

theorem chiT_gen (hpk : p ^ k ∣ q - 1) {gu : (ZMod q)ˣ}
    (hg : ∀ u : (ZMod q)ˣ, u ∈ Subgroup.zpowers gu) :
    chiT hp hpk hg gu = zetaM (p ^ k)

theorem jacobiSumT_eq_reduce (hpk : p ^ k ∣ q - 1) {gu : (ZMod q)ˣ}
    (hg : ∀ u : (ZMod q)ˣ, u ∈ Subgroup.zpowers gu) {f : ℕ → ℕ}
    (hf : ∀ x ∈ Finset.Icc 1 (q - 2), ((gu : ZMod q)) ^ f x = 1 - ((gu : ZMod q)) ^ x)
    (a b : ℕ) :
    jacobiSumT n p k q f a b
      = reduceCycT n p k hp hk (jacobiSum (chiT hp hpk hg ^ a) (chiT hp hpk hg ^ b))

theorem testBit_interleave_owned (f : Fin m → ℕ) {i : ℕ} {j : Fin m}
    (h : A.slotOf i = some j) :
    (A.interleave f).testBit i = (f j).testBit (A.rank i)

theorem offsetIn_lt_offsetIn {cap : Fin m → Option ℕ} {t : ℕ} {j j' : Fin m}
    (hact : ActiveIn cap t j') (hlt : j < j') :
    offsetIn cap t j' < offsetIn cap t j

theorem rankFun_eq {cap : Fin m → Option ℕ} {t i : ℕ}
    (h1 : roundStart cap t ≤ i) (h2 : i < roundStart cap (t + 1)) :
    rankFun cap i = t

theorem exists_posFun_eq {cap : Fin m → Option ℕ} {t i : ℕ}
    (h1 : roundStart cap t ≤ i) (h2 : i < roundStart cap (t + 1)) :
    ∃ j, ActiveIn cap t j ∧ posFun cap j t = i

theorem owned_of_round {cap : Fin m → Option ℕ} {t i : ℕ}
    (h1 : roundStart cap t ≤ i) (h2 : i < roundStart cap (t + 1)) :
