    {f : ℕ → T} (hg : g.gen = fun n => if n < card then some (f n) else none) :
    @Contiguous T g

theorem contiguous_of_boundedBijOn {T : Type*} (g : ExhaustiveGenerator T) {card : ℕ}
    {f : (n : ℕ) → n < card → T}
    (hg : g.gen = fun n => if h : n < card then some (f n h) else none) :
